"""Hidden behavioral tests for jo: coercion. Generated by pbkit from the gold binary."""


def test_table_00(run):
    "coercion table row for ''"
    r = run(args=['--', '-s', 's=', '-n', 'n=', '-b', 'b=', 'a='])
    assert r.stdout == b'{"s":"","n":0,"b":false,"a":null}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_table_01(run):
    "coercion table row for 'string'"
    r = run(args=['--', '-s', 's=string', '-n', 'n=string', '-b', 'b=string', 'a=string'])
    assert r.stdout == b'{"s":"string","n":6,"b":true,"a":"string"}\n'
    assert r.stderr == b''
    assert r.returncode == 0


