def test_man_object_example(run):
    r = run(args=['-p', '--', '-s', 'a=true', 'b=true', '-s', 'c=123', 'd=123', '-b', 'e=1', '-b', 'f=true', '-n', 'g=This is a test', '-b', 'h=This is a test'])
    assert r.stdout == b'{\n   "a": "true",\n   "b": true,\n   "c": "123",\n   "d": 123,\n   "e": true,\n   "f": true,\n   "g": 14,\n   "h": true\n}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_man_array_example(run):
    r = run(args=['-a', '--', '-s', '123', '-n', 'This is a test', '-b', 'C_Rocks', '456'])
    assert r.stdout == b'["123",14,true,456]\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_coerce_without_double_dash(run):
    r = run(args=['-s', 'a=1'])
    assert r.stdout == b''
    assert r.stderr == b"<PROG>: invalid option -- 's'\nUsage: <PROG> [-a] [-B] [-D] [-d keydelim] [-p] [-e] [-n] [-o outfile] [-v] [-V] [-f file] [--] [-s|-n|-b] [word...]\n\tword is key=value or key@value\n\t-a creates an array of words\n\t-B disable boolean true/false/null detection\n\t-D deduplicate object keys\n\t-d key will be object path separated by keydelim\n\t-f load file as JSON object or array\n\t-p pretty-prints JSON on output\n\t-e quit if stdin is empty do not wait for input\n\t-s coerce type guessing to string\n\t-b coerce type guessing to bool\n\t-n coerce type guessing to number\n\t-o output to the given file\n\t-v show version\n\t-V show version in JSON\n"
    assert r.returncode == 255


def test_coerce_n_without_double_dash(run):
    r = run(args=['-n', 'a=1'])
    assert r.stdout == b'{"a":1}\n'
    assert r.stderr == b''
    assert r.returncode == 0


def test_coerce_twice(run):
    r = run(args=['--', '-s', '-n', 'a=1'])
    assert r.stdout == b'{"a":1}\n'
    assert r.stderr == b"Argument `-n' is neither k=v nor k@v\n"
    assert r.returncode == 0


